#!/usr/bin/env npx tsx
/**
 * Update ESL summaries with Feynman-style content (400-800 words).
 */

import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

const summaries: Record<string, string> = {
  // Chapter 1: Introduction
  "Introduction to Statistical Learning": `Imagine you're a doctor trying to predict whether a patient will have a second heart attack, or you're building a mail system that needs to filter spam from legitimate emails, or you're at the post office trying to read handwritten ZIP codes automatically. In all these cases, you have historical data showing past outcomes, and you want to learn patterns that will help you predict future ones accurately. This is the fundamental problem that **statistical learning** addresses: using observed data to build models that make accurate predictions about cases we haven't seen yet. Think of it like learning to recognize faces. You've seen thousands of faces in your life, and somehow your brain has extracted patterns that let you recognize your friend in a crowd, even if they're wearing a hat or sunglasses you've never seen them in before. Statistical learning formalizes this intuitive process mathematically, giving us rigorous tools to learn from examples. The key insight underlying all of statistical learning is that we have **features** - measurable characteristics like a patient's age, blood pressure, cholesterol level, or the frequency of certain words in an email - and we have an **outcome** we want to predict, like whether someone will have a heart attack or whether an email is spam. We observe many examples where we know both the features and the true outcome; this collection of labeled examples is our **training data**. From this data, we build a prediction function that takes in features and outputs a predicted outcome. When the outcome is categorical, like spam versus legitimate email or cancer versus no cancer, we call the problem **classification**. When the outcome is numerical, like predicting a stock price or a patient's blood pressure, we call it **regression**. The critical distinction in the field is between **supervised learning**, where we have labeled outcomes in our training data to guide the learning process, and **unsupervised learning**, where we only observe features and must discover hidden structure on our own - like finding natural groupings in customer behavior data without being told what the groups should be. Real examples bring these abstract ideas to life. Predicting prostate cancer risk from clinical measurements involves regression since PSA is a continuous number. Recognizing handwritten digits from pixel intensities is a classification problem with ten possible classes. Understanding gene expression patterns across cancer tumors might be unsupervised, seeking to cluster similar cancer types together. Each of these involves the same fundamental challenge: learning a function $f(X)$ that accurately predicts outcome $Y$ from features $X$, while crucially being able to generalize beyond the specific examples we trained on. The ability to generalize - to perform well on new, unseen data - is what separates true learning from mere memorization of the training examples.`,

  "Introduction and Variable Types": `Before we can build prediction models that work in the real world, we need a precise language for describing exactly what we're working with. Think of it like learning to cook: before you can follow any recipe, you need to understand the difference between a teaspoon and a tablespoon, between sautéing and simmering, between chopping and mincing. In statistical learning, our ingredients are **variables**, and they come in two fundamentally different flavors that behave very differently and require different mathematical treatment. **Quantitative variables** are numerical measurements where arithmetic operations make sense: you can meaningfully compute the average age of patients in a study, subtract one temperature from another to find how much it changed, or calculate the ratio of two stock prices. These variables live on a numerical scale where distances and differences have meaning. **Qualitative variables**, also called categorical or discrete variables, represent distinct categories where arithmetic is meaningless: you cannot sensibly average "male" and "female," compute "spam minus legitimate email," or claim that one blood type is numerically greater than another. This fundamental distinction between variable types profoundly affects how we build and interpret prediction models. For quantitative outcomes like predicting a house's sale price or a patient's expected survival time, we use **regression** methods that predict a number on a continuous scale. For categorical outcomes like classifying an email as spam or legitimate, diagnosing a tumor as malignant or benign, or recognizing which digit a handwritten character represents, we use **classification** methods that predict which discrete category something belongs to. The mathematical approaches differ substantially because regression aims to get close to a target number while classification aims to pick the right category. Our input variables, the features we use to make predictions, can be of either type and often we work with a mixture of both. A spam filter might use the frequency of certain words (quantitative) alongside whether the sender is in your contacts list (categorical). A medical diagnosis system might combine lab measurements (quantitative) with symptoms reported as present or absent (categorical). Interestingly, we often convert categorical inputs to numerical codes for mathematical convenience - representing male and female as 0 and 1, or creating separate indicator variables for each category - but this is purely a computational trick, not a claim that male is somehow "less than" female. The outcome variable we're trying to predict is conventionally denoted $Y$, while inputs are written as $X = (X_1, X_2, \ldots, X_p)$ where $p$ represents the number of features we're using. A prediction model is simply a function $\hat{Y} = \hat{f}(X)$ that takes in feature values and produces a predicted outcome. The hat notation $\hat{}$ indicates that these are estimates, our best guesses based on learned patterns, rather than known truths about the world.`,

  "Linear Models and Least Squares": `When facing a prediction problem for the first time, where should we even begin? The simplest approach, and one that turns out to be surprisingly effective across a wide range of real-world problems, is to assume that the relationship between inputs and output is approximately linear - meaning that the output changes by a constant amount for each unit change in any input variable. This assumption gives us the **linear model**, whose power lies not just in its simplicity but in its remarkable interpretability and the solid theoretical foundation we can build around it. Imagine you're trying to predict house prices based on square footage and number of bedrooms. A linear model says: predicted price equals some base amount, plus dollars per square foot times the square footage, plus dollars per bedroom times the number of bedrooms. Each coefficient tells us directly and explicitly how much the predicted price changes when we adjust one feature while holding all others fixed. This interpretability is invaluable when we need to understand and explain our predictions, not just make them. Mathematically, we write this relationship as $\hat{Y} = \hat{\beta}_0 + \sum_{j=1}^{p} X_j \hat{\beta}_j$, where $\hat{\beta}_0$ is the intercept or base amount, and each $\hat{\beta}_j$ represents how much the outcome $Y$ is expected to change per unit increase in feature $X_j$. But given a set of training data, how do we actually find the best values for these coefficients? The **least squares** method provides an elegant and powerful answer: we should choose the coefficients that minimize the sum of squared prediction errors across all our training examples. If for each training case $i$ we predict $\hat{y}_i$ but actually observe $y_i$, we want to minimize $\sum_{i=1}^{N}(y_i - \hat{y}_i)^2$, the residual sum of squares. Squaring the errors serves multiple purposes: it means large mistakes are penalized more heavily than small ones, it treats over-predictions and under-predictions symmetrically, and most importantly, the mathematics works out cleanly to give us a unique best answer with a closed-form solution. Geometrically, we can visualize this as fitting a hyperplane (a multidimensional flat surface) through our cloud of data points, positioning it to minimize the total squared vertical distance from each observed point to the plane. This approach dates back to Gauss and Legendre in the early 1800s, and despite being over two centuries old, it remains absolutely central to modern statistical practice. Linear models can be extended naturally to handle categorical outcomes through methods like **linear discriminant analysis**, which finds linear boundaries that optimally separate different classes. Despite their simplicity and strong assumptions, linear models often perform remarkably well in practice, sometimes outperforming more flexible methods, and their transparency makes them invaluable when we need to understand which features matter and how they influence predictions.`,

  "Nearest Neighbor Methods": `Linear models rest on a strong assumption: that the relationship between inputs and outputs follows a straight-line pattern, or at least can be well approximated by one. But what if the true relationship is curved, wavy, contains sudden jumps, or involves complex interactions between variables that a linear function could never capture? **Nearest neighbor methods** take a radically different approach that makes almost no assumptions about the functional form of the relationship at all. The underlying idea is beautifully intuitive and mirrors how humans often make decisions: to predict the outcome for a new case, find the training cases that are most similar to it and use their outcomes as your prediction. If you want to predict whether someone will enjoy a particular movie, look at what people with similar taste preferences thought of it. If you want to estimate the price of a house, look at what similar nearby houses sold for. Formally, given a new point $x$ where we want to make a prediction, we find the $k$ training points that are closest to $x$ according to some distance measure, typically Euclidean distance, and then we predict by averaging their $Y$ values for a regression problem or by taking a majority vote among their class labels for classification. The parameter $k$ controls the smoothness or locality of our predictions and represents a fundamental choice we must make. With $k=1$, we simply copy the outcome of the single most similar training case, which gives us extremely local and flexible predictions but ones that can be noisy and erratic because they depend entirely on that one neighbor. With larger values of $k$, we average over more neighbors, producing smoother and more stable predictions that may however miss important local patterns if we average over too large a region. This tradeoff between flexibility and stability is our first encounter with one of the most fundamental concepts in all of statistical learning: the **bias-variance tradeoff**. Small values of $k$ give flexible predictions that can capture complex local patterns (low bias) but that vary wildly depending on which particular training cases happen to be nearby (high variance). Large values of $k$ give stable predictions that are less sensitive to individual training points (low variance) but may systematically fail to capture true patterns in the data (high bias). Finding the sweet spot depends on how much training data we have available and how complex the true underlying relationship actually is. Nearest neighbor methods have a profound theoretical advantage: with enough training data and an appropriate choice of $k$, they can approximate any continuous function to arbitrary precision. However, they also suffer from what's called the **curse of dimensionality**: in high-dimensional spaces with many input features, the very concept of "nearness" becomes problematic as points spread out and even our closest neighbors may actually be quite far away, severely degrading prediction quality.`,

  "Statistical Decision Theory": `We've now seen two quite different approaches to prediction: linear models that assume a simple global structure, and nearest neighbors that make local predictions with minimal assumptions. Is there a unified framework that tells us what an "optimal" prediction would even mean, and how these different methods relate to that ideal? **Statistical decision theory** provides exactly this theoretical foundation, giving us rigorous tools to think about what we're trying to achieve and how well any method can possibly perform. The key insight is to think about the prediction problem probabilistically rather than deterministically. The outcome $Y$ isn't determined exactly by the input features $X$; rather, knowing $X$ tells us something about the probability distribution of possible $Y$ values we might observe. For any specific value of $X$, there's an entire distribution of $Y$ outcomes that could occur - some more likely than others, but none certain. Given this fundamental uncertainty, what should we predict? The answer depends on how we measure the cost of being wrong. If we want to minimize the average squared error of our predictions, a natural and common choice, then the optimal prediction turns out to be surprisingly simple: it's the **conditional expectation** $f(x) = E[Y|X=x]$, which is just the average value of $Y$ among all cases in the population that share the same input value $x$. This is a beautiful and powerful result. The best squared-error predictor isn't some complicated function we need to hunt for; it's simply the mean of $Y$ for each value of $X$. The challenge is that we don't know this conditional expectation - we have to estimate it from our finite training data. Both linear models and nearest neighbors can be understood as different strategies for estimating this same target quantity. Linear models assume that the conditional mean is a linear function of $X$ and use least squares to estimate the coefficients. Nearest neighbors estimate the local conditional mean by averaging $Y$ values among training points whose $X$ values are near our prediction point. For classification problems where $Y$ is categorical, the analogous optimal rule is different but equally elegant: we should classify each case to the class that has the highest probability given the observed features. This rule is called the **Bayes classifier**, and the error rate it achieves represents a fundamental floor on performance - no other classifier can do better on average. The difference between the Bayes error rate and what our actual classifier achieves tells us how much room for improvement remains.`,

  "Local Methods in High Dimensions": `Nearest neighbor methods seem wonderfully flexible: they can approximate essentially any pattern given enough training data, without requiring us to specify any particular functional form in advance. So why don't we simply use them for all prediction problems? The answer lies in a phenomenon called the **curse of dimensionality**, which reveals a fundamental and inescapable challenge that arises in high-dimensional spaces and affects all flexible local methods, not just nearest neighbors. Here's the key intuition. Imagine data points scattered uniformly in a box. In one dimension, where our data lives on a line segment, your nearest neighbor is typically quite close to you. In two dimensions, where data spreads across a square, points have more room to spread out and neighbors are typically farther away. In three dimensions with a cube, even farther. As we continue adding dimensions, the amount of space grows exponentially, and even a large collection of data points becomes incredibly sparse - most of the vast multidimensional space is completely empty. To find enough neighbors to average over for a reliable prediction, we must reach surprisingly far from our target point in every direction. But if our neighbors are far away, their $Y$ values may be quite different from what $Y$ would be at our actual target point, making the local average a poor prediction. The mathematics behind this phenomenon is striking and sobering. In $p$ dimensions, the expected distance to the nearest point in a sample of $N$ observations grows proportionally to $N^{-1/p}$. Consider what happens with $p=10$ dimensions: to achieve the same average distance to your nearest neighbor as you would have in one dimension with just 100 data points, you would need approximately $100^{10} = 10^{20}$ observations in ten dimensions - a number far exceeding the number of atoms in a human body. This isn't just a theoretical curiosity affecting nearest neighbors in isolation. The curse of dimensionality is a fundamental limitation on any method that tries to make predictions by examining local behavior without imposing structural assumptions on the problem. The only escape route is to make assumptions that constrain what patterns we're looking for. Linear models assume a simple global linear structure and therefore work reasonably well even in high dimensions, as long as the true relationship is approximately linear. More sophisticated methods try to find a middle ground: they impose enough structure to avoid the curse while remaining flexible enough to capture important nonlinear patterns. The bias-variance tradeoff takes center stage here - in high dimensions, we must accept more bias through stronger assumptions to achieve reasonable variance and reliable predictions.`,

  "Statistical Models and Supervised Learning": `We've spoken informally about the relationship between input features $X$ and the outcome $Y$ we want to predict, but it's time to be mathematically precise about what we're actually trying to learn and what makes the prediction problem fundamentally challenging. A **statistical model** specifies a formal mathematical relationship between inputs and outputs, typically written as $Y = f(X) + \varepsilon$. In this formulation, $f$ is a fixed but unknown function that captures the systematic, predictable relationship between $X$ and $Y$ - the signal we're trying to learn. The term $\varepsilon$ represents random error that captures all the variation in $Y$ that cannot be predicted from $X$ alone - the irreducible noise in the system. Think of predicting students' test scores from the number of hours they studied. The function $f$ captures the general trend: more study typically leads to higher scores. But individual students differ in ways we can't measure: some are naturally talented, some had a bad night's sleep before the exam, some guessed lucky on multiple choice questions. All these unmeasured factors get absorbed into $\varepsilon$. This framework clarifies precisely what supervised learning is trying to accomplish: we're attempting to estimate the unknown function $f$ from training data where we've observed both inputs $X$ and corresponding outcomes $Y$. Different learning methods make different assumptions about what kind of function $f$ might be. Linear regression assumes $f(X) = \beta_0 + \beta_1 X_1 + \ldots + \beta_p X_p$, a specific linear form with unknown coefficients. More flexible methods like neural networks allow $f$ to be a complex composition of many nonlinear transformations. The fundamental tradeoff in choosing among these approaches is that simpler, more restrictive function classes are easier to estimate reliably from limited data but may systematically miss true patterns; richer, more flexible function classes can capture more complex relationships but require more data and are prone to fitting noise along with signal. The additive error structure $Y = f(X) + \varepsilon$ also reveals something profound about the limits of prediction. Even if we somehow knew the true function $f$ exactly, our predictions would still have errors because of the random component $\varepsilon$. The variance of $\varepsilon$, written $\text{Var}(\varepsilon)$ or $\sigma^2$, sets an absolute floor on prediction error that no method, no matter how sophisticated, can ever beat. This is called the **irreducible error**, and recognizing its existence helps set realistic expectations for any prediction task.`,

  "Function Approximation and Structured Regression": `We've established that supervised learning fundamentally means estimating an unknown function $f$ from training data. But the space of all possible functions is infinite-dimensional - how could we possibly search through it to find the right one? The answer is that we don't try to search the entire space. Instead, we restrict our search to a specific **function class** that we believe contains good approximations to the truth. This is the essential idea behind **structured regression** and indeed behind all practical learning methods. Think of choosing a musical instrument to play a melody. A piano restricts you to discrete notes at fixed pitches, while a violin allows you to slide continuously across any pitch. Neither can produce every possible sound, but within their constraints, each can play an enormous variety of music. Similarly, when we choose to fit linear functions, we're restricting ourselves to flat, straight-line relationships, but within that class we can represent any linear pattern by selecting appropriate coefficient values. When we choose polynomial functions, we allow curves of various shapes. Neural networks permit extremely complex patterns by composing many simple nonlinear transformations. Each choice represents assumptions about what kind of relationship we expect to find, and matching these assumptions well to the true problem structure is crucial for success. The mathematical formulation of this idea is to minimize a **loss function** over a parameterized family of functions. If our function class is written as $\{f_\theta : \theta \in \Theta\}$, meaning functions indexed by some parameter vector $\theta$, we seek the parameter value $\hat{\theta} = \arg\min_\theta \sum_{i=1}^N L(y_i, f_\theta(x_i))$ that minimizes total loss on the training data. The loss function $L$ measures how bad a prediction is. For squared error loss $L(y, \hat{y}) = (y-\hat{y})^2$ combined with linear functions, minimizing gives us the familiar least squares regression. Different choices of loss lead to different methods with different properties: absolute error loss $L(y, \hat{y}) = |y-\hat{y}|$ gives **robust regression** that's less sensitive to outliers; the negative log-likelihood loss leads to **maximum likelihood estimation** with its strong statistical justification. The choice of function class determines what patterns we can possibly capture. Linear functions can only represent flat relationships. Polynomial functions allow various curved shapes but can wiggle wildly. Splines allow locally flexible curves that join smoothly at specified points. The art and science of statistical learning lies in matching the flexibility of the function class to the true complexity of the problem at hand.`,

  "Classes of Restricted Estimators": `Given the vast zoo of statistical learning methods that exist, each with its own name, algorithm, and tuning parameters, how should we organize our thinking about what's actually available and when each approach might be most appropriate? A helpful framework is to categorize methods by the type of restriction or regularization they impose on the function $f$ being estimated. Each type of restriction embodies different assumptions about the problem structure and leads to different behavior in practice. **Roughness penalty methods** allow quite flexible functions but explicitly penalize complexity, balancing the fit to data against smoothness. Instead of minimizing only the prediction error on training data, we minimize a combined objective: prediction error plus a term measuring how "rough" or "wiggly" the fitted function is. The classic example is the smoothing spline, which minimizes $\sum_{i=1}^N(y_i - f(x_i))^2 + \lambda \int [f''(x)]^2 dx$. The integral term measures total squared curvature, penalizing functions that bend sharply. The tuning parameter $\lambda$ controls this tradeoff explicitly: large values of $\lambda$ force very smooth functions with potentially high bias but low variance; small values allow wiggly functions that fit the training data closely but may have high variance. **Kernel methods and local regression** build predictions using weighted averages, where the weights depend on the distance from the prediction point to each training point. A kernel function specifies how these weights decay with distance, and a bandwidth parameter controls how quickly they decay - equivalently, how local the averaging is. Nearest neighbor methods fit here with uniform weights on the $k$ closest points and zero weight on all others. Nadaraya-Watson kernel regression uses smooth, gradually decaying weights. **Basis expansion methods** represent the function $f$ as a linear combination of simpler building-block functions: $f(x) = \sum_{m=1}^M \beta_m h_m(x)$. The basis functions $h_m$ might be polynomial terms, trigonometric functions for periodic patterns, wavelets for localized features, or learned functions as in neural networks. Once the basis is chosen, function estimation reduces to estimating the linear combination coefficients $\beta_m$, a much simpler problem. **Dictionary methods** generalize this by considering a very large collection of potential basis functions and automatically selecting a sparse subset that best explains the data. Methods like LASSO, matching pursuit, and boosting all fall in this category, achieving both flexibility and interpretability through principled sparsity.`,

  "Model Selection and Bias-Variance Tradeoff": `Every statistical learning method we've discussed involves choices that control the method's complexity and flexibility: the number of neighbors $k$ in nearest neighbors, the regularization strength $\lambda$ in ridge regression, the number of hidden units in a neural network, which variables to include in a linear model. How do we make these crucial choices wisely? The answer connects directly to perhaps the single most fundamental concept in all of statistical learning: the **bias-variance tradeoff**. To understand this tradeoff precisely, consider what happens when we make a prediction $\hat{f}(x_0)$ at some new point $x_0$ using a model estimated from training data. Our expected prediction error, averaged over all possible training datasets we might have collected and all possible values of the outcome at $x_0$, can be decomposed mathematically into three distinct components: $E[(Y - \hat{f}(x_0))^2] = \text{Var}(\hat{f}(x_0)) + [\text{Bias}(\hat{f}(x_0))]^2 + \text{Var}(\varepsilon)$. The first term, **variance**, measures how much our predictions at this point would fluctuate if we repeated the entire process with different training datasets drawn from the same population. High variance means our predictions are unstable, sensitive to the particular training examples we happened to observe. The second term, **bias squared**, measures systematic error: how far the average prediction across all possible training sets deviates from the true value we're trying to predict. High bias means we're consistently off in a particular direction no matter which training set we use. The third term is the irreducible error that comes from the inherent noise in the outcome, which no method can reduce. Complex, flexible models tend to have low bias because they can capture intricate patterns, but high variance because they fit too closely to particular training data. Simple, rigid models have high bias because they may miss true patterns, but low variance because they're stable across different samples. As we increase model complexity by adding features, using more neighbors with smaller weights, or reducing regularization strength, bias typically decreases while variance increases. The total error is minimized at an intermediate complexity level that balances these two sources of error, and this optimal complexity depends on both the true underlying signal complexity and the amount of training data available. With more data, we can afford more complex models because variance decreases. Practical **model selection** methods like cross-validation and information criteria help us find this balance empirically.`,

  // Chapter 3: Linear Methods for Regression
  "Linear Regression Fundamentals": `Linear regression is the true workhorse of statistical modeling, used countless times every day across science, business, medicine, and engineering. Understanding it deeply, with all its nuances and extensions, provides an essential foundation for understanding virtually everything else in statistical learning. The core idea is deceptively simple: predict a quantitative outcome as a weighted combination of input features plus a constant baseline. Mathematically, we model the prediction as $\hat{Y} = \hat{\beta}_0 + \hat{\beta}_1 X_1 + \hat{\beta}_2 X_2 + \ldots + \hat{\beta}_p X_p$. The parameter $\hat{\beta}_0$ is called the intercept - it's the predicted value when all input features equal zero. Each other coefficient $\hat{\beta}_j$ tells us precisely how much the predicted outcome changes when feature $X_j$ increases by one unit, with all other features held constant. This interpretability is one of linear regression's greatest strengths: you can look at the coefficients and immediately understand how each variable influences the prediction. To find the best coefficient values from training data, we use the **least squares** criterion: choose the coefficients that make the sum of squared prediction errors as small as possible. Specifically, we minimize $\text{RSS}(\beta) = \sum_{i=1}^N (y_i - \beta_0 - \sum_{j=1}^p x_{ij}\beta_j)^2$, where $N$ is the number of training observations. This criterion has a beautiful geometric interpretation: we're finding the hyperplane in the space of inputs that is closest to our observed outcome values, where "closest" is measured by total squared vertical distance. The solution can be written elegantly in matrix notation as $\hat{\beta} = (X^T X)^{-1} X^T y$, where $X$ is the matrix of input features (with a column of ones for the intercept) and $y$ is the vector of observed outcomes. This formula assumes that the matrix $X^T X$ is invertible, which requires that no input feature can be written as a perfect linear combination of the others - a condition called "no perfect multicollinearity." A critical concept is the **degrees of freedom** of the fit, which measures model complexity in a way that accounts for the data used. With $p$ input features plus an intercept, we're estimating $p+1$ parameters. This leaves $N-p-1$ degrees of freedom for estimating the variance of our errors, and this ratio of sample size to parameters critically affects how reliably we can estimate and how much we should trust our results.`,

  "Prostate Cancer Example and Gauss-Markov": `To make these ideas concrete and to appreciate both the power and limitations of linear regression, consider a real medical prediction problem: estimating prostate-specific antigen (PSA) levels from clinical measurements in 97 men with prostate cancer. The data includes eight potential predictors: log cancer volume, log prostate weight, patient age, log of benign prostatic hyperplasia amount, seminal vesicle invasion status, log of capsular penetration, Gleason score, and percentage of Gleason scores 4 or 5. With so many potential predictors and limited data, a fundamental question arises: should we use all eight features in our model, or might a simpler model with fewer features actually perform better? This is where statistical theory becomes practically important. The **Gauss-Markov theorem** tells us something profound about the optimality of least squares estimation. Among all estimators of the regression coefficients that are both linear functions of the outcome $y$ and unbiased (correct on average across many hypothetical datasets), ordinary least squares has the smallest variance - it produces the most stable, reliable coefficient estimates possible within this class. This sounds like a strong endorsement, but there's a critical caveat: the theorem only compares unbiased estimators. If we're willing to accept some bias - some systematic error in our coefficient estimates - we might achieve substantially lower variance, and depending on the situation, this tradeoff might favor us overall. This insight motivates the shrinkage methods we'll explore soon, like ridge regression and lasso. The prostate cancer data also powerfully illustrates the challenge of **multicollinearity** - correlation among the predictors. Several of these clinical measurements are related to each other: larger tumors tend to go with higher Gleason scores, capsular penetration relates to tumor volume, and so on. When predictors are correlated, the least squares coefficient estimates become unstable. Small random changes in the data can cause large changes in individual coefficients, even when the overall predictions remain relatively stable. The standard errors of the coefficients become large, making it difficult to determine with confidence which features are truly important versus which appear important only due to chance. Looking at the prostate data results, we find that only a subset of the eight predictors have statistically significant coefficients, but this doesn't necessarily mean the others are useless for prediction.`,

  "Multiple Regression and Multiple Outputs": `The basic linear regression model extends naturally in two important and complementary directions that arise constantly in real applications. First, **multiple regression** handles many input features simultaneously, estimating how each contributes to the outcome while accounting for the others. We've already encountered this, but the interplay between features in a multiple regression model introduces critical subtleties that are essential to understand. When we add a new predictor to a model that already contains other predictors, the coefficient for that new variable represents its effect *after controlling for* all the other variables already in the model. This "partial" or "adjusted" effect can differ dramatically from the "marginal" effect we would see if we regressed the outcome on just that one variable alone. A famous example illustrates why this matters: ice cream sales and drowning deaths are positively correlated, but this doesn't mean ice cream causes drowning. Adding temperature to the regression reveals that ice cream has essentially no effect on drowning once temperature is accounted for - both are simply driven by hot summer weather. The geometry of multiple regression provides deep insight into what the coefficients really mean. We can decompose the least squares predictions into orthogonal contributions from each variable. This is formalized by the **Gram-Schmidt orthogonalization** procedure: for each predictor $X_j$, regress it on all the other predictors and take the residual - this residual captures what is unique to $X_j$ that isn't already captured by the other predictors. Then regress the outcome $Y$ on this residual. The coefficient you obtain equals the multiple regression coefficient for $X_j$. This shows that each coefficient captures only the unique, independent information in its corresponding predictor. The second extension is to **multiple output variables**: predicting several different outcome measures simultaneously from the same set of inputs. For instance, we might want to predict both systolic and diastolic blood pressure, or multiple gene expression levels, or various customer behavior metrics. If we have $K$ different outcomes, we could certainly fit $K$ separate regressions, each predicting one outcome from the inputs. But fitting them jointly can offer advantages, especially when we believe the outcomes are related to each other. Information about one outcome can help improve predictions for another.`,

  "Subset Selection Methods": `When we have many potential predictor variables available, a natural question arises: should we include all of them in our model, or should we select a subset? Including irrelevant predictors wastes degrees of freedom and can increase prediction variance without reducing bias, potentially hurting overall prediction accuracy. Including too few predictors leads to bias and missed patterns. The simplest approach to navigating this tradeoff is **subset selection**: find the single best model among all possible subsets of the available predictors. Conceptually clean as this sounds, it's computationally formidable. With $p$ potential predictors, there are $2^p$ possible subsets to consider - one for each combination of including or excluding each predictor. For $p=10$, that's about a thousand subsets, easily manageable. For $p=20$, it's over a million. For $p=30$, over a billion. For the really high-dimensional datasets common in genomics and other modern applications with thousands of potential predictors, explicit enumeration is hopelessly infeasible. Several practical strategies help navigate the space of possible subsets. **Best subset selection** explicitly evaluates all $2^p$ subsets, but this is only practical when $p$ is small, typically no more than 30 or 40. For each possible subset size $k$ (from 0 to $p$), we find the single best $k$-predictor model as judged by training error, typically the residual sum of squares. We then choose among these best models of each size using cross-validation or an information criterion that penalizes complexity. **Forward stepwise selection** provides a computationally tractable greedy approximation. We start with an empty model containing only the intercept, then at each step add the single predictor that most improves the fit among those not yet included. We stop when no remaining predictor significantly improves the model. This explores roughly $1 + p + (p-1) + \ldots \approx p^2/2$ models rather than $2^p$, making it feasible even for large $p$. **Backward stepwise selection** works in reverse: start with all predictors included, then at each step remove the predictor whose removal hurts the fit least. Both greedy approaches are heuristics that don't guarantee finding the globally best subset, but they often work well in practice and are far more computationally feasible than exhaustive search.`,

  "Ridge Regression": `Subset selection makes a hard, discrete choice at each step: include a predictor completely or exclude it entirely. But perhaps we should consider a more nuanced approach that keeps all predictors while smoothly controlling their influence on the prediction. This is exactly what **ridge regression** does by shrinking regression coefficients toward zero rather than forcing them all the way to zero. The idea is elegantly simple: modify the least squares objective function to include a penalty term that punishes large coefficient values. Specifically, ridge regression minimizes $\sum_{i=1}^N (y_i - \beta_0 - \sum_{j=1}^p x_{ij}\beta_j)^2 + \lambda \sum_{j=1}^p \beta_j^2$. The first part is the ordinary residual sum of squares, measuring fit to the training data. The second part, $\lambda \sum_j \beta_j^2$, is the penalty: the sum of squared coefficients multiplied by a tuning parameter $\lambda \geq 0$. Setting $\lambda = 0$ gives ordinary least squares - no penalty at all. As $\lambda$ increases, coefficients are forced to be smaller, approaching zero as $\lambda \to \infty$. Why would shrinking coefficients toward zero help? When predictor variables are correlated with each other, ordinary least squares coefficient estimates become unstable. The estimates can be large in magnitude and often opposite in sign for correlated predictors, even when the overall predictions remain reasonable. This instability manifests as high variance: different training samples lead to wildly different coefficient estimates. Ridge regression stabilizes estimation by pulling coefficients toward zero, accepting some bias in exchange for substantially reduced variance. For problems with many correlated predictors, this tradeoff often improves prediction accuracy on new data. The ridge solution has a beautiful closed form: $\hat{\beta}^{\text{ridge}} = (X^T X + \lambda I)^{-1} X^T y$. Notice how similar this is to the ordinary least squares solution $(X^T X)^{-1} X^T y$, but with $\lambda I$ added to the matrix being inverted. This addition has a crucial effect: it makes the matrix invertible even when $X^T X$ is singular or nearly singular due to perfect or near-perfect collinearity among predictors. Geometrically, ridge regression is shrinking the least squares estimate toward the origin, with the amount of shrinkage depending on the eigenstructure of $X^T X$. Directions in coefficient space corresponding to small eigenvalues, which are estimated most unreliably, get shrunk the most.`,

  "The Lasso and Comparison": `Ridge regression shrinks coefficients smoothly toward zero but never actually sets any coefficient exactly to zero - every predictor remains in the model with some nonzero weight, however small. For interpretation and parsimony, we might want actual variable selection: a model where some coefficients are precisely zero and the corresponding predictors are definitively excluded. The **lasso** (Least Absolute Shrinkage and Selection Operator) achieves this through a seemingly small but consequential change: replacing the squared penalty on coefficients with an absolute value penalty. Lasso minimizes $\sum_{i=1}^N (y_i - \beta_0 - \sum_{j=1}^p x_{ij}\beta_j)^2 + \lambda \sum_{j=1}^p |\beta_j|$. The penalty $\sum_j |\beta_j|$ is called an $L_1$ penalty because it's the sum of absolute values, which is the $L_1$ norm of the coefficient vector. Contrast this with ridge's $L_2$ penalty $\sum_j \beta_j^2$, the squared $L_2$ norm. This change from squared to absolute value has profound mathematical and practical consequences. The $L_1$ penalty function has corners at zero: it's not smooth where any coefficient equals zero. Because of these corners, the optimization solution often lands exactly at a corner, setting some coefficients precisely to zero. The lasso thus performs shrinkage and variable selection simultaneously, automatically identifying a subset of predictors to include while shrinking their coefficients. The geometric interpretation makes this intuitive. For ridge regression, the constraint region - all coefficient vectors satisfying $\sum_j \beta_j^2 \leq t$ - is a ball, smooth and round. For lasso, the constraint region $\sum_j |\beta_j| \leq t$ is a diamond shape with corners on the coordinate axes. The least squares solution is some point in coefficient space, and we want to find the closest point in the constraint region. A smooth ball first touches the least squares solution on its surface, which is generically not at a corner. A diamond first touches at a corner where one or more coordinates are zero, yielding a sparse solution. Which method works better depends entirely on the true underlying structure. If many predictors have small but nonzero effects, ridge's gentle uniform shrinkage works well. If only a few predictors truly matter and others are noise, lasso's sparsity correctly zeros out the irrelevant ones and can outperform ridge.`,

  "Least Angle Regression": `The lasso penalty leads to a mathematically interesting but computationally challenging optimization problem because the absolute value function isn't differentiable at zero. How can we efficiently compute lasso solutions, and can we understand the structure of how variables enter and leave the model as the regularization strength changes? **Least Angle Regression (LAR)** provides an elegant algorithm that not only computes lasso solutions efficiently but also gives beautiful insight into the variable selection process. The LAR algorithm starts with all coefficients set to zero - maximum regularization where no predictor is selected. It then builds the model up in discrete steps. At each step, the algorithm identifies which predictor is most correlated with the current residual - this is the variable that, if added to the model, would most improve the fit. Standard forward stepwise regression would simply add this variable with its full least squares coefficient. LAR takes a more refined approach: it moves in a direction that increases the coefficient of this selected variable gradually, just until some other predictor becomes equally correlated with the residual. At this point, both predictors are tied for most helpful, and LAR changes direction to move along a path where both coefficients increase together, keeping both predictors equally correlated with the residual. This continues: as more predictors tie for maximum correlation, they all join the active set and their coefficients evolve together. The name "least angle" comes from the geometry of the update direction, which makes equal angles with all the currently active predictors. A remarkable and initially surprising discovery is that with a simple modification, the LAR algorithm exactly traces out the entire path of lasso solutions as the regularization parameter $\lambda$ varies from infinity down to zero. The modification is this: if at any point along the path a coefficient crosses zero and would change sign, we remove that variable from the active set and continue. This modified LAR algorithm produces the complete lasso path with computational cost similar to fitting a single ordinary least squares model - vastly more efficient than computing the lasso solution separately for many values of $\lambda$. The path also reveals interpretable structure: predictors that enter the model early (at high $\lambda$) are the most predictive, while predictors that enter late may be noise or redundant.`,

  "PCR and Partial Least Squares": `When predictors are highly correlated with each other, both subset selection and shrinkage methods face challenges in distinguishing which individual predictors matter. An alternative philosophical approach is **dimension reduction**: instead of selecting among or shrinking individual predictors, we transform the original predictors into a smaller set of derived features that capture most of the predictive information while being more stable to estimate. **Principal Components Regression (PCR)** is the classic dimension reduction approach. We first compute the principal components of the predictor matrix $X$ - these are new variables that are linear combinations of the original predictors, constructed to be uncorrelated with each other and ordered by how much variance they explain in the predictor space. The first principal component is the direction in predictor space along which the predictors vary most; the second is the direction of maximum variance perpendicular to the first; and so on. We then regress the outcome $Y$ on just the first $M$ principal components instead of the original $p$ predictors, where $M < p$ is chosen by cross-validation. Since the components are constructed to be orthogonal, this regression is particularly simple: the coefficient for each component is just the univariate regression coefficient from regressing $Y$ on that component alone, and the predictions are the sum of these separate contributions. Using fewer than $p$ components achieves dimension reduction. The hope underlying PCR is that the directions of maximum variance in the predictors are also the directions most related to the outcome. This hope is often but not always fulfilled - it's entirely possible that a direction with small predictor variance is actually highly predictive of the outcome, and pure PCR would miss this. **Partial Least Squares (PLS)** addresses this limitation by finding directions that are explicitly chosen to have high variance in $X$ *and* high correlation with $Y$ simultaneously. The first PLS direction maximizes the squared covariance between the linear combination $X\alpha$ and the outcome $Y$, balancing spread in $X$ against predictiveness for $Y$. Despite its conceptual appeal, PLS doesn't consistently outperform PCR in empirical comparisons - sometimes the unsupervised principal component directions are indeed the predictive ones, making the supervised correction unnecessary.`,

  "Comparison and Multiple Outcomes": `We've now explored a rich variety of methods for regression with many predictors: subset selection, ridge regression, lasso, elastic net, principal components regression, partial least squares. Each has its own assumptions, strengths, and weaknesses. How do they compare to each other, and when should we choose which approach? Extensive simulation studies and theoretical analysis have revealed consistent patterns that guide practical choices. When the true underlying relationship is **sparse** - only a small subset of predictors actually matter - lasso tends to excel. It can find the relevant predictors, zero out the irrelevant ones, and achieve excellent prediction accuracy with an interpretable model. When many predictors have small but genuine effects, so the truth is **dense**, ridge regression often performs better because it includes all variables with appropriately shrunken coefficients rather than arbitrarily selecting some and ignoring others. Principal components regression works well when the predictive information truly lies along the high-variance directions in predictor space, which is common when predictors represent variations on a few underlying themes. The ratio of sample size to number of predictors fundamentally affects what's possible. With many more observations than predictors ($N >> p$), multiple methods often perform similarly - there's enough data to estimate complex models reliably. As the ratio becomes less favorable, differences emerge. When $N < p$, ordinary least squares breaks down entirely because the system is underdetermined, but ridge regression, lasso, and dimension reduction methods remain applicable and can perform well. Correlated predictors create particular challenges that different methods handle differently. Lasso tends to arbitrarily select one predictor from a correlated group and ignore the others, which can be misleading if interpretation is the goal. Elastic net, which combines lasso and ridge penalties, handles correlated predictors more gracefully by tending to select or exclude correlated predictors together. Ridge keeps all predictors but distributes weight among correlated ones. The extension to **multiple output variables** creates additional opportunities. When we predict multiple related outcomes from the same predictors, we can exploit their correlation structure: information about one outcome may help predict another.`,

  "Advanced Lasso Topics": `The lasso has become central to modern statistics and machine learning, spawning an entire ecosystem of extensions, efficient algorithms, and theoretical understanding. Several advanced topics deserve attention for anyone who wants to use these methods seriously. A fundamental challenge is conducting valid **statistical inference after lasso selection**. Classical statistical theory assumes we chose which variables to include in our model before looking at the data, but lasso selects variables based on the data itself. The selected model is random, depending on the particular sample, and this creates subtle problems for computing confidence intervals and p-values using standard formulas. One influential approach uses **conditional inference**: given that lasso selected a particular set of variables, what can we say about their true coefficients? This conditioning leads to polyhedral constraints on the data space and modified confidence intervals that account for the selection process. The **group lasso** extends sparsity from individual variables to groups of related variables. Instead of penalizing $\sum_j |\beta_j|$, we penalize $\sum_{g=1}^G \|\beta_g\|_2$, where $\beta_g$ is the vector of coefficients for the $g$-th group of predictors and $\|\cdot\|_2$ is the Euclidean norm. This penalty tends to set entire groups to zero together or include them together, which is natural when predictors have a group structure - for instance, a categorical variable represented by multiple dummy indicators, or a set of polynomial terms for a single underlying variable. The **fused lasso** adds penalties on differences between adjacent coefficients: $\lambda_1 \sum_j |\beta_j| + \lambda_2 \sum_j |\beta_{j+1} - \beta_j|$. This simultaneously encourages sparsity and smoothness, yielding coefficient sequences that are piecewise constant. Such structure is natural when predictors have a natural ordering, like spatial or temporal data. **Pathwise coordinate descent** provides efficient algorithms for computing lasso and its extensions. The idea is to cycle repeatedly through coordinates, updating each coefficient while holding all others fixed. For the lasso, each such coordinate update has a closed-form solution involving "soft-thresholding" - shrinking toward zero by a fixed amount. Starting from a very sparse solution at large $\lambda$ and using "warm starts" as $\lambda$ decreases makes the algorithm fast and stable.`,
};

async function main() {
  console.log("=== UPDATING ESL SUMMARIES ===\n");

  const concepts = await prisma.concept.findMany({
    where: { book: { title: { contains: "Statistical" } } },
    include: { branch: true },
    orderBy: [{ branch: { chapterNumber: "asc" } }, { orderInBranch: "asc" }],
  });

  console.log(`Found ${concepts.length} concepts to update\n`);

  let updated = 0;
  let skipped = 0;
  const wordCounts: number[] = [];

  for (const concept of concepts) {
    const summary = summaries[concept.title];
    if (!summary) {
      console.log(`[SKIP] ${concept.title} - No summary defined`);
      skipped++;
      continue;
    }

    const wordCount = summary.split(/\s+/).length;
    wordCounts.push(wordCount);

    await prisma.concept.update({
      where: { id: concept.id },
      data: { summary },
    });

    const status = wordCount >= 400 && wordCount <= 800 ? "✓" : "⚠";
    console.log(`[${status}] ${concept.title} - ${wordCount} words`);
    updated++;
  }

  console.log(`\n=== COMPLETE ===`);
  console.log(`Updated: ${updated}`);
  console.log(`Skipped: ${skipped}`);

  if (wordCounts.length > 0) {
    const min = Math.min(...wordCounts);
    const max = Math.max(...wordCounts);
    const avg = Math.round(wordCounts.reduce((a, b) => a + b, 0) / wordCounts.length);
    console.log(`Word counts: min=${min}, max=${max}, avg=${avg}`);
  }
}

main()
  .catch(console.error)
  .finally(() => prisma.$disconnect());
